package com.lyrashop.order.dto;
import java.math.BigDecimal;import java.time.Instant;import jakarta.validation.constraints.*;
public record AdminVoucherRequest(@NotBlank @Size(max=30) @Pattern(regexp="[A-Za-z0-9_-]+") String code,@NotBlank @Size(max=255) String label,@NotBlank @Pattern(regexp="discount|shipping") String type,@NotBlank @Pattern(regexp="PERCENT|FIXED|FREESHIP") String discountType,@NotNull @DecimalMin("0.00") @Digits(integer=10,fraction=2) BigDecimal discountValue,@DecimalMin("0.00") @Digits(integer=10,fraction=2) BigDecimal maxDiscountAmount,@NotNull @DecimalMin("0.00") @Digits(integer=10,fraction=2) BigDecimal minimumOrderAmount,@NotNull Instant startsAt,@NotNull Instant endsAt,@Positive Integer totalUsageLimit,@NotNull @Positive Integer perUserLimit,boolean active){}
